/**
 * Title: Aether Nebula (WebGL)
 * Description: Domain-warped nebula gas in your theme's accent colors that gathers at the screen's edges, thins behind the chat, parts around the cursor and now and then blooms.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const INTENSITY     = 0.85;  // how strongly the gas shows (0-1)
const MOTION        = 1;     // drift speed; 0 holds the nebula still and stops blooms (0-2)
const REDUCED_SPEED = 0.15;  // share of the drift kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.75;  // how much the gas thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const GAS_SCALE     = 1.6;   // size of the cloud structures; lower is larger (0.6-4)
const WARP          = 3;     // how swirled the gas is (0-6)
const STAR_DENSITY  = 0.5;   // faint stars behind the gas, dark themes only (0-1)
const CURSOR_PUSH   = 1;     // how far the gas parts around the cursor (0-3)
const BLOOM_EVERY   = 70;    // average seconds between stellar blooms; 0 turns them off (0-300)
const RENDER_SCALE  = 0.5;   // resolution of the gas; it is soft, so half is plenty (0.25-1)
const MAX_FPS       = 30;    // frame cap; the gas moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#6f8cff';  // gas color when not following the theme
const COLOR_B       = '#a46cf0';  // second gas color
const COLOR_C       = '#4fd2e6';  // highlight and bloom color
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform float u_dark;',
	'uniform vec4 u_bloom;',
	'uniform vec2 u_col;',
	'float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }',
	'float noise(vec2 p) {',
	'	vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);',
	'	return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
	'}',
	'float fbm(vec2 p) {',
	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	float t = u_time;',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	vec2 dm = px - m;',
	'	float md = length(dm);',
	'	vec2 push = u_mouse.z * ' + CURSOR_PUSH.toFixed(3) + ' * dm / (md + 1.0) * exp(-md / 240.0) * 0.08;',
	'	vec2 p = px / res.y * ' + GAS_SCALE.toFixed(3) + ' + push;',
	'	vec2 q = vec2(fbm(p + vec2(0.0, t * 0.012)), fbm(p + vec2(5.2, 1.3) - t * 0.010));',
	'	vec2 r = vec2(fbm(p + ' + WARP.toFixed(3) + ' * q + vec2(1.7, 9.2) + t * 0.015), fbm(p + ' + WARP.toFixed(3) + ' * q + vec2(8.3, 2.8) - t * 0.013));',
	'	float f = fbm(p + ' + WARP.toFixed(3) + ' * r);',
	'	float dens = smoothstep(0.38, 0.95, f) * 0.85 + smoothstep(0.62, 0.95, length(r)) * 0.3;',
	'	vec3 col = mix(u_c1, u_c2, clamp(q.x * 1.4 - 0.2, 0.0, 1.0));',
	'	col = mix(col, u_c3, clamp(r.y * r.y * 1.4, 0.0, 1.0));',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float edge = 0.7 + 0.3 * smoothstep(0.1, 0.75, length(px / res - 0.5));',
	'	float a = dens * calm * edge * ' + INTENSITY.toFixed(3) + ' * mix(0.65, 0.9, u_dark);',
	'	vec2 cell = floor(px / 90.0);',
	'	vec2 sp = (cell + vec2(hash(cell), hash(cell + 7.1))) * 90.0;',
	'	float lit = step(1.0 - ' + STAR_DENSITY.toFixed(3) + ' * 0.55, hash(cell + 3.3));',
	'	float tw = 0.55 + 0.45 * sin(t * (0.6 + hash(cell + 1.9) * 1.6) + hash(cell) * 6.283);',
	'	float s = lit * tw * smoothstep(2.4, 0.0, length(px - sp)) * u_dark * mix(0.35, 1.0, calm) * 0.8;',
	'	vec2 b = vec2(u_bloom.x, res.y - u_bloom.y);',
	'	float life = u_bloom.z;',
	'	float env = smoothstep(0.0, 2.5, life) * (1.0 - smoothstep(3.5, 10.0, life));',
	'	float ba = u_bloom.w * env * exp(-length(px - b) / 170.0) * (0.35 + 0.65 * smoothstep(0.3, 0.8, f));',
	'	vec3 bloomCol = mix(u_c3, vec3(1.0), 0.35 * u_dark);',
	'	vec3 starCol = mix(vec3(1.0), u_c1, 0.3);',
	'	float outA = clamp(a + s + ba * 0.8, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(col * a + starCol * s + bloomCol * ba * 0.8, vec3(outA)), outA);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
let loc = {};
let w = 0, h = 0;
let last = 0, time = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const bloom = { x: 0, y: 0, age: 1000, strength: 0, wait: BLOOM_EVERY * 0.5 };
const colors = { c1: hexToRgb(COLOR_A), c2: hexToRgb(COLOR_B), c3: hexToRgb(COLOR_C), dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent2;
	colors.c3 = t.rgb.accent3;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_mouse', 'u_c1', 'u_c2', 'u_c3', 'u_dark', 'u_bloom', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// ── Blooms: a slow swell of light beside the chat column, never over it ──
function updateBloom(dt) {
	bloom.age += dt;
	if (BLOOM_EVERY <= 0 || MOTION <= 0 || reduced || bloom.age < 10) return;
	bloom.wait -= dt;
	if (bloom.wait > 0) return;
	// The margins beside the column, inside the chat area so the sidebar can't cover a bloom
	const lo = column ? column.left : 0, hi = column ? column.right : w;
	const left = Math.max(0, colX() - colHalf() - lo), right = Math.max(0, hi - colX() - colHalf());
	if (left + right < 80) return;
	const r = Math.random() * (left + right);
	bloom.x = r < left ? lo + r * 0.85 : hi - (r - left) * 0.85;
	bloom.y = h * (0.15 + Math.random() * 0.7);
	bloom.strength = 0.5 + Math.random() * 0.5;
	bloom.age = 0;
	bloom.wait = BLOOM_EVERY * (0.6 + Math.random() * 0.8);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * MOTION * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	updateBloom(dt);
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.x, mouse.y, mouse.amount);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform4f(loc.u_bloom, bloom.x, bloom.y, bloom.age, bloom.strength);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' })
		|| canvas.getContext('webgl', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' });
	if (!gl) {
		console.warn('Aether Nebula: WebGL is not available, so the nebula is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Aether Nebula:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Aether Nebula:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

dark.customCSS:
:root {
	--amb-glass: color-mix(in oklab, var(--color-gray-950) 72%, transparent);
	--amb-sidebar: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
	--amb-bubble: color-mix(in oklab, var(--color-gray-800) 55%, transparent);
	--amb-selected: color-mix(in oklab, var(--tdp-accent) 14%, transparent);
	--amb-line: color-mix(in oklab, var(--tdp-accent) 26%, transparent);
	--amb-glow: color-mix(in oklab, var(--tdp-accent) 70%, transparent);
	--amb-ring: color-mix(in oklab, var(--tdp-accent) 20%, transparent);
	--amb-edge: solid;
	--amb-ink: var(--tdp-accent-2);
	--amb-bright: var(--tdp-accent);
	--amb-strong: var(--tdp-accent);
	--amb-on-bright: var(--color-gray-950);
	--amb-phosphor: 0 0 0.6em color-mix(in oklab, var(--tdp-accent) 30%, transparent);
}

/* An amber phosphor terminal, or its printout in the light modes. Monospace
   prose with a prompt before each heading; the shapes stay Open WebUI's.
   !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--amb-glass) !important;
	border-color: var(--amb-line) !important;
	backdrop-filter: blur(14px);
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
	transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#message-input-container:focus-within {
	border-color: var(--amb-glow) !important;
	box-shadow: 0 0 0 3px var(--amb-ring), 0 0 24px -6px var(--amb-ring);
}
.chat-user .rounded-3xl {
	background-color: var(--amb-bubble) !important;
	box-shadow: inset 0 0 0 1px var(--amb-line);
}
#sidebar {
	background-color: var(--amb-sidebar) !important;
	border-inline-end: 1px var(--amb-edge) var(--amb-line);
}
#sidebar-chat-item.selected { background-color: var(--amb-selected); }
.markdown-prose { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; color: var(--amb-ink); text-shadow: var(--amb-phosphor); }
.markdown-prose :is(h1, h2, h3, a) { color: var(--amb-bright); }
.markdown-prose strong { color: var(--amb-strong); }
.markdown-prose :is(h1, h2, h3)::before { content: "> "; opacity: 0.55; }
.markdown-prose :is(hr, blockquote) { border-color: var(--amb-line); }
::selection { background-color: var(--amb-bright); color: var(--amb-on-bright); }
html { scrollbar-color: var(--amb-line) transparent; }

dark.canvasScript:
/**
 * Title: Data Stream
 * Description: Packets of light in your theme's accents stream along faint horizontal lanes like network traffic, dim behind the chat, swirl around the cursor and ping out from a tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const LANE_GAP      = 14;    // distance between lanes, in px (8-40)
const PACKETS       = 280;   // most packets on screen at once (40-400)
const SPAWN_RATE    = 34;    // new packets per second (2-60)
const SPEED         = 0.8;     // travel speed; 0 holds the traffic still (0-3)
const REDUCED_SPEED = 0.15;  // share of the speed kept when the viewer asks to reduce motion (0-1)
const RIGHTWARD     = 0.7;   // share of lanes flowing left to right (0-1)
const BRIGHTNESS    = 1;     // strength of the packets (0.2-1.5)
const LANE_LINES    = 0.35;   // strength of the faint lane lines (0-1)
const CENTER_CALM   = 0.8;   // how much the traffic dims behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const VORTEX        = 1;     // how strongly packets swirl around the cursor (0-3)
const VORTEX_RADIUS = 180;   // reach of the swirl, in px (60-400)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#3cb4dc';  // first packet color when not following the theme
const COLOR_B       = '#3c7cdc';  // second packet color
const COLOR_C       = '#62d8f2';  // third packet color
const LINE_COLOR    = '#1e6e96';  // lane lines
/* ──────────────────────────────────────────── */

const MAX = 400;
const CAP = Math.max(1, Math.min(MAX, Math.round(PACKETS)));
const TONES = 3;
const MAX_LANES = 256;

let canvas, ctx;
let w = 0, h = 0, dpr = 1, laneCount = 1;
let last = 0, reduced = false, dark = true, spawnAcc = 0, count = 0, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };

// Packet pool
const px = new Float32Array(MAX), py = new Float32Array(MAX), baseY = new Float32Array(MAX);
const pw = new Float32Array(MAX), ph = new Float32Array(MAX);
const vx = new Float32Array(MAX), vy = new Float32Array(MAX), ox = new Float32Array(MAX);
const pa = new Float32Array(MAX), boost = new Float32Array(MAX);
const tone = new Uint8Array(MAX);
// Lanes
const laneY = new Float32Array(MAX_LANES), laneV = new Float32Array(MAX_LANES), laneDepth = new Float32Array(MAX_LANES);

let colors = { tones: [COLOR_A, COLOR_B, COLOR_C].map(hexToRgb), line: hexToRgb(LINE_COLOR) };
const sprites = [];   // [tone * 2 + (leftward ? 1 : 0)]
let laneStyle = null;

function hexToRgb(hex) {
	const n = parseInt(String(hex).slice(1, 7), 16) || 0;
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgba(c, a) {
	return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a.toFixed(3) + ')';
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function calm(x) {
	const d = Math.abs(x - colX()) / colHalf();
	const s = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		colors = { tones: [hexToRgb(c.accent), hexToRgb(c.accent3), hexToRgb(c.accent2)], line: hexToRgb(c.muted) };
	}
	build();
}

// Packet sprites (a bright head, a fading tail, a soft halo) and the lane-line gradient, rebuilt on theme, resize and layout
function build() {
	if (!ctx || !w) return;
	for (let k = 0; k < TONES; k++) {
		const c = colors.tones[k];
		for (let dir = 0; dir < 2; dir++) {
			const sp = sprites[k * 2 + dir] || new OffscreenCanvas(96, 16);
			const g = sp.getContext('2d');
			g.clearRect(0, 0, 96, 16);
			const head = dir ? 0 : 96;
			const body = g.createLinearGradient(96 - head, 0, head, 0);
			body.addColorStop(0, rgba(c, 0));
			body.addColorStop(0.45, rgba(c, 0.5));
			body.addColorStop(0.97, rgba(c, 1));
			body.addColorStop(1, rgba(c, 0.6));
			g.fillStyle = body;
			g.globalAlpha = dark ? 0.25 : 0.14;
			g.fillRect(0, 2, 96, 12);
			g.globalAlpha = 1;
			g.fillRect(0, 6, 96, 4);
			sprites[k * 2 + dir] = sp;
		}
	}
	const lg = ctx.createLinearGradient(0, 0, w, 0);
	const la = LANE_LINES * (dark ? 0.09 : 0.08);
	for (let s = 0; s <= 16; s++) lg.addColorStop(s / 16, rgba(colors.line, la * calm((s / 16) * w)));
	laneStyle = lg;
}

function spawn(atX, lane, dirSign, bright) {
	if (count >= CAP) return;
	const i = count++;
	const l = lane >= 0 ? lane : (Math.random() * laneCount) | 0;
	const dir = dirSign || (laneV[l] > 0 ? 1 : -1);
	const depth = laneDepth[l];
	pw[i] = (10 + Math.random() * 44) * (0.6 + depth * 0.6);
	ph[i] = (1.4 + Math.random() * 1.8) * (0.7 + depth * 0.5);
	baseY[i] = laneY[l];
	py[i] = laneY[l] + (Math.random() - 0.5) * LANE_GAP * 0.35;
	vx[i] = Math.abs(laneV[l]) * dir * (0.7 + Math.random() * 0.6);
	vy[i] = 0;
	ox[i] = 0;
	px[i] = atX !== undefined ? atX : dir > 0 ? -pw[i] : w + pw[i];
	pa[i] = (0.5 + Math.random() * 0.5) * (0.55 + depth * 0.45);
	boost[i] = bright ? 1 : 0;
	tone[i] = (Math.random() * TONES) | 0;
}

function kill(i) {
	const j = --count;
	if (i === j) return;
	px[i] = px[j]; py[i] = py[j]; baseY[i] = baseY[j]; pw[i] = pw[j]; ph[i] = ph[j];
	vx[i] = vx[j]; vy[i] = vy[j]; ox[i] = ox[j]; pa[i] = pa[j]; boost[i] = boost[j]; tone[i] = tone[j];
}

function layout() {
	laneCount = Math.max(1, Math.min(MAX_LANES, Math.floor(h / LANE_GAP)));
	for (let l = 0; l < laneCount; l++) {
		laneY[l] = (l + 0.5) * (h / laneCount);
		laneDepth[l] = Math.random();
		laneV[l] = (30 + Math.random() * 150) * (0.5 + laneDepth[l] * 0.7) * (Math.random() < RIGHTWARD ? 1 : -1);
	}
	count = 0;
	for (let k = 0; k < CAP * 0.6; k++) spawn(Math.random() * w, -1, 0, false);
}

function size(nw, nh, ndpr) {
	w = nw;
	h = nh;
	dpr = Math.min(2, ndpr || 1);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	layout();
	build();
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx || !laneStyle) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const pace = SPEED * (reduced ? REDUCED_SPEED : 1);
	mouse.target = Math.max(0, mouse.target - dt * 0.6);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);

	spawnAcc += SPAWN_RATE * dt * Math.min(1, pace);
	while (spawnAcc >= 1) { spawn(undefined, -1, 0, false); spawnAcc--; }

	const swirl = VORTEX * mouse.amount * (reduced ? 0.3 : 1) * 260;
	const r = VORTEX_RADIUS;
	const spring = Math.min(1, dt * 4);
	for (let i = count - 1; i >= 0; i--) {
		const dx = px[i] - mouse.x, dy = py[i] - mouse.y;
		const d2 = dx * dx + dy * dy;
		if (swirl > 0 && d2 < r * r && d2 > 1) {
			// Swirl: push along the tangent; the extra speed relaxes back, so packets never stall or reverse for good
			const d = Math.sqrt(d2);
			const f = (1 - d / r) * swirl * dt;
			vy[i] += dx / d * f;
			ox[i] -= dy / d * f * 0.5;
		}
		vy[i] += (baseY[i] - py[i]) * 6 * dt;
		vy[i] *= 1 - spring * 0.5;
		ox[i] *= 1 - spring * 0.4;
		boost[i] = Math.max(0, boost[i] - dt * 0.6);
		px[i] += (vx[i] + ox[i]) * pace * dt;
		py[i] += vy[i] * dt;
		if ((vx[i] > 0 && px[i] > w + pw[i] + 10) || (vx[i] < 0 && px[i] < -pw[i] - 10) || py[i] < -40 || py[i] > h + 40) kill(i);
	}

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);

	if (LANE_LINES > 0) {
		ctx.strokeStyle = laneStyle;
		ctx.lineWidth = dpr > 1 ? 0.5 : 1;
		ctx.beginPath();
		for (let l = 0; l < laneCount; l++) {
			ctx.moveTo(0, laneY[l]);
			ctx.lineTo(w, laneY[l]);
		}
		ctx.stroke();
	}

	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	const base = BRIGHTNESS * (dark ? 1 : 1.3);
	for (let i = 0; i < count; i++) {
		const len = pw[i], hh = ph[i] * 4;
		const a = Math.min(1, (pa[i] + boost[i]) * base * calm(px[i] + len * 0.5));
		if (a < 0.01) continue;
		ctx.globalAlpha = a;
		ctx.drawImage(sprites[tone[i] * 2 + (vx[i] < 0 ? 1 : 0)], px[i], py[i] - hh * 0.5, len, hh);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			if (d.theme) applyTheme(d.theme);
			size(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			build();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown': {
			// A tap pings its lane: two bright packets leave the tap point in opposite directions
			if (reduced || !w) break;
			const l = Math.max(0, Math.min(laneCount - 1, Math.floor(d.y / (h / laneCount))));
			spawn(d.x, l, 1, true);
			spawn(d.x, l, -1, true);
			break;
		}
	}
};

