			wait[i] = 6 + Math.random() * 10;
			gx[i] = hx[i] + (Math.random() - 0.5) * 2 * DRIFT;
			gy[i] = hy[i] + (Math.random() - 0.5) * 2 * DRIFT;
		}
		nx[i] += (gx[i] - nx[i]) * ease;
		ny[i] += (gy[i] - ny[i]) * ease;
		energy[i] *= Math.exp(-dt * 1.8);
	}
	if (FIRE_EVERY > 0) {
		fireWait -= speed;
		if (fireWait <= 0) {
			fireWait = FIRE_EVERY * (0.5 + Math.random());
			fire(Math.floor(Math.random() * inputs), 0.6 + Math.random() * 0.4, 0.5);
		}
	}
	// A moving cursor wakes the nearest node; a resting one does not
	wakeWait -= dt;
	if (mouse.amount > 0.4 && wakeWait <= 0) {
		wakeWait = 0.35;
		const n = nearest(mouse.x, mouse.y, CURSOR_REACH);
		if (n >= 0) fire(n, 0.6, 0.5);
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const k = pl[p];
		if (k < 0) continue;
		pp[p] += ps[p] * speed;
		if (pp[p] < 1) continue;
		pl[p] = -1;
		const to = lt[k];
		energy[to] = Math.min(1, energy[to] + 0.35 * pb[p]);
		if (pb[p] > 0.25 && to < firstOfLast) fire(to, pb[p] * 0.7, reduced ? CASCADE * 0.4 : CASCADE);
	}
}

function draw() {
	ctx.clearRect(0, 0, w, h);
	const k = dark ? 1 : 0.8;
	for (let i = 0; i < linkCount; i++) {
		const a = lf[i], b = lt[i];
		const calm = lc[i];
		ctx.globalAlpha = Math.min(1, (LINK_ALPHA * (0.5 + lw[i] * 0.5) + Math.max(energy[a], energy[b]) * 0.18) * calm * k);
		ctx.strokeStyle = col.link;
		ctx.lineWidth = 1 + lw[i] * 0.5;
		ctx.beginPath();
		ctx.moveTo(nx[a], ny[a]);
		ctx.lineTo(nx[b], ny[b]);
		ctx.stroke();
	}
	for (let p = 0; p < MAX_PULSES; p++) {
		const l = pl[p];
		if (l < 0) continue;
		const a = lf[l], b = lt[l], f = pp[p];
		const x = nx[a] + (nx[b] - nx[a]) * f, y = ny[a] + (ny[b] - ny[a]) * f;
		ctx.globalAlpha = Math.min(1, (0.4 + pb[p] * 0.6) * band(x) * k * Math.min(1, f * 6, (1 - f) * 6));
		ctx.drawImage(pulseSprite, x - 12, y - 12);
	}
	for (let i = 0; i < nodeCount; i++) {
		const e = energy[i], c = ncalm[i] * k;
		// Every node keeps a faint halo at rest, which swells when it fires
		ctx.globalAlpha = Math.min(1, (0.22 + e * 0.6) * c);
		ctx.drawImage(haloSprite, nx[i] - 16, ny[i] - 16);
		ctx.globalAlpha = Math.min(1, (0.55 + e * 0.45) * c);
		ctx.fillStyle = col.node;
		ctx.beginPath();
		ctx.arc(nx[i], ny[i], NODE_RADIUS, 0, 6.2832);
		ctx.fill();
		if (e > 0.1) {
			ctx.globalAlpha = Math.min(1, e * 0.8 * c);
			ctx.fillStyle = col.core;
			ctx.beginPath();
			ctx.arc(nx[i], ny[i], NODE_RADIUS * 0.5, 0, 6.2832);
			ctx.fill();
		}
	}
	ctx.globalAlpha = 1;
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	mouse.target = Math.max(0, mouse.target - dt * 0.8);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 5);
	update(dt);
	draw();
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			resize(d.width, d.height, d.dpr);
			requestAnimationFrame(frame);
			break;
		case 'resize':
			resize(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) build();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'mousedown': {
			// A tap fires the nearest node down every link; a single soft pulse when motion is reduced
			const n = nearest(d.x, d.y, CURSOR_REACH * 1.3);
			if (n >= 0) fire(n, reduced ? 0.5 : 1, reduced ? 0.4 : 1);
			break;
		}
	}
};

light.customCSS:
:root {
	--bio-glass: color-mix(in oklab, var(--color-gray-50) 62%, transparent);
	--bio-sidebar: color-mix(in oklab, var(--color-gray-50) 68%, transparent);
	--bio-bubble: color-mix(in oklab, var(--color-gray-200) 55%, transparent);
	--bio-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--bio-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--bio-glow: color-mix(in oklab, var(--tdp-accent) 60%, transparent);
	--bio-ring: color-mix(in oklab, var(--tdp-accent) 20%, transparent);
	--bio-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--bio-accent: color-mix(in oklab, var(--tdp-accent-2) 75%, var(--color-gray-900));
	--bio-strong: color-mix(in oklab, var(--tdp-accent-2) 60%, var(--color-gray-900));
}

/* Membrane glass over the neural net: magenta tissue, cyan signal. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--bio-glass) !important;
	border-color: var(--bio-line) !important;
	backdrop-filter: blur(18px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--bio-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--bio-glow) !important;
	box-shadow: 0 0 0 3px var(--bio-ring), 0 12px 40px -16px var(--bio-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--bio-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--bio-line);
}
#sidebar {
	background-color: var(--bio-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--bio-line);
}
#sidebar-chat-item.selected { background-color: var(--bio-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--bio-accent); font-weight: 400; letter-spacing: 0.04em; }
.markdown-prose a { color: var(--bio-accent); text-decoration-color: var(--bio-glow); }
.markdown-prose strong { color: var(--bio-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--bio-glow); }
.markdown-prose hr { border-color: var(--bio-line); }
html { scrollbar-color: var(--bio-line) transparent; }
::selection { background-color: var(--bio-ring); }

