oled.customCSS:
:root {
	--plasma-glass: color-mix(in oklab, var(--color-gray-850) 62%, transparent);
	--plasma-sidebar: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
	--plasma-bubble: color-mix(in oklab, var(--color-gray-700) 50%, transparent);
	--plasma-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--plasma-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--plasma-glow: color-mix(in oklab, var(--tdp-accent) 55%, transparent);
	--plasma-ring: color-mix(in oklab, var(--tdp-accent) 16%, transparent);
	--plasma-shade: color-mix(in oklab, var(--color-gray-950) 65%, transparent);
	--plasma-accent: var(--tdp-accent);
	--plasma-cool: color-mix(in oklab, var(--tdp-accent-3) 45%, white);
}

/* Reactor console glass: cool containment surfaces, thermal orange for what runs hot. !important only where Canvas FX transparency clears a background first. */
#message-input-container {
	background-color: var(--plasma-glass) !important;
	border-color: var(--plasma-line) !important;
	backdrop-filter: blur(18px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--plasma-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--plasma-glow) !important;
	box-shadow: 0 0 0 3px var(--plasma-ring), 0 12px 40px -16px var(--plasma-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--plasma-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--plasma-line);
}
#sidebar {
	background-color: var(--plasma-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--plasma-line);
}
#sidebar-chat-item.selected { background-color: var(--plasma-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--plasma-accent); font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; text-transform: uppercase; letter-spacing: 0.08em; }
.markdown-prose a { color: var(--plasma-cool); text-decoration-color: var(--plasma-line); }
.markdown-prose blockquote { border-inline-start-color: var(--plasma-glow); }
.markdown-prose hr { border-color: var(--plasma-line); }
html { scrollbar-color: var(--plasma-line) transparent; }
::selection { background-color: var(--plasma-ring); }

