	'	float flare = smoothstep(0.5, 0.0, abs(fbm(rel * 2.5 + t * 0.3) - 0.5)) * exp(-d * 1.6);',
	'	col += u_hot * warn * flare * (0.55 + 0.45 * sin(t * 4.0 + n * 10.0)) * 0.7;',
