		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
		case 'context': {
			// Prefer the exact count; a new, empty chat cools the core back to idle
			const tokens = d.exactTokens != null ? d.exactTokens : (d.estimatedTokens || 0);
			target = d.messages === 0 ? 0 : Math.min(1, (tokens / MAX_TOKENS) * GROWTH_SPEED);
			break;
		}
	}
};

