	'	float v = 0.0, a = 0.5;',
	'	mat2 m = mat2(1.6, 1.2, -1.2, 1.6);',
	'	for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }',
	'	return v;',
	'}',
	// Two layers of embers rising through cells, each lit cell holding one spark
	'float embers(vec2 p, float t) {',
	'	float acc = 0.0;',
	'	for (int i = 0; i < 2; i++) {',
	'		float fi = float(i);',
	'		vec2 ep = vec2(p.x * (14.0 + fi * 8.0) + sin(t * 0.4 + fi * 2.0 + p.y * 3.0) * 0.4, p.y * 9.0 - t * (0.9 + fi * 0.5));',
	'		vec2 id = floor(ep), f = fract(ep);',
	'		float d = length(f - (0.2 + 0.6 * hash2(id)));',
	'		float tw = 0.6 + 0.4 * sin(t * 1.6 + hash(id) * 40.0);',
	'		acc += smoothstep(0.11, 0.0, d) * tw * step(0.82, hash(id + 2.7)) * (1.2 - fi * 0.4);',
	'	}',
	'	return acc;',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	vec2 p0 = px / res.y;',
	'	float t = u_time;',
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float side = smoothstep(0.75, 1.6, band);',
	'	float floorHeat = 1.0 - smoothstep(0.0, ' + Math.max(0.05, FORGE_HEIGHT).toFixed(3) + ', px.y / res.y);',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float stoke = exp(-length(px - m) / 200.0) * u_mouse.z * ' + CURSOR_HEAT.toFixed(3) + ';',
	'	float mask = clamp(max(side, floorHeat * 0.9) + stoke * 0.7, 0.0, 1.0);',
	'	vec2 p = p0 + (vec2(noise(p0 * 24.0 + t * 2.2), noise(p0 * 24.0 + 9.1 + t * 2.0)) - 0.5) * 0.006 * ' + SHIMMER.toFixed(3) + ' * (0.3 + mask);',
	'	float K = ' + NOISE_SCALE.toFixed(3) + ';',
	'	float q1 = fbm(p * K * 1.15 + vec2(u_drift, -t * 0.02));',
	'	float q2 = fbm(p * K * 1.15 + vec2(4.4, 1.3) - vec2(u_drift * 0.6, 0.0));',
	'	float hgt = fbm(p * K + 2.3 * vec2(q1, q2));',
	'	float channel = 1.0 - smoothstep(0.0, mix(0.018, 0.06, mask), abs(hgt - 0.47 + 0.03 * q1));',
	'	float lake = mix(0.10, 0.30, mask);',
	'	float skin = smoothstep(0.25, 0.75, noise(p * 9.0 + vec2(q1, q2) * 3.0 + t * 0.05));',
	'	float pool = (1.0 - smoothstep(lake - 0.07, lake, hgt)) * mix(0.35, 1.0, skin);',
	'	float heat = max(channel * mix(0.45, 1.0, mask), pool * mask);',
	'	float pulse = 0.85 + 0.15 * sin(t * 0.9 + q1 * 6.0);',
	'	float ridged = 1.0 - abs(2.0 * noise(p * 7.0 + vec2(q2, q1) * 2.0) - 1.0);',
	'	float cracks = pow(ridged, 9.0) * (1.0 - heat) * mix(0.08, 1.0, mask);',
	'	float hm = ' + HEAT.toFixed(3) + ' * (1.0 + stoke * 0.5) * mix(0.8, 1.0, u_dark);',
	'	vec3 lava = mix(mix(u_deep, u_hot, pow(heat, 1.4)), u_core, pow(heat, 6.0) * pulse * 0.55 * u_dark);',
	'	float la = smoothstep(0.0, 0.6, heat) * mix(0.18, 1.0, mask) * calm * min(1.0, hm * pulse) * mix(0.7, 0.92, u_dark);',
	'	float ra = (1.0 - heat) * mask * calm * (0.55 + 0.5 * noise(p * 11.0)) * mix(0.10, 0.30, u_dark);',
	'	float ca = cracks * calm * min(1.0, 0.9 * hm * pulse) * mix(0.7, 1.0, u_dark);',
	'	float ga = heat * mask * calm * 0.25 * hm;',
	'	float ea = embers(p0, t) * max(side, floorHeat * 0.6) * calm * calm * ' + EMBER_AMOUNT.toFixed(3) + ' * smoothstep(1.0, 0.7, px.y / res.y) * mix(0.7, 1.0, u_dark);',
	'	vec4 o = vec4(u_rock * ra, ra);',
	'	o = vec4(u_hot * ga, ga) + o * (1.0 - ga);',
	'	o = vec4(min(lava, vec3(1.0)) * la, la) + o * (1.0 - la);',
	'	o = vec4(u_hot * ca, ca) + o * (1.0 - ca);',
	'	o = vec4(mix(u_hot, u_core, 0.6) * ea, ea) + o * (1.0 - ea);',
	'	o = clamp(o, 0.0, 1.0);',
	'	gl_FragColor = vec4(min(o.rgb, vec3(o.a)), o.a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
const loc = {};
let w = 0, h = 0;
let last = 0, time = 0, drift = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0, sx: -10000, sy: -10000, lean: 0 };
const colors = { deep: hexToRgb(COLOR_DEEP), hot: hexToRgb(COLOR_HOT), core: hexToRgb(COLOR_CORE), rock: [0, 0, 0], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function mix3(a, b, k) { return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k]; }

// Running lava takes accent, cooling lava accent2, the core leans toward white on dark themes
function applyTheme(t) {
	if (t) colors.dark = t.dark === false ? 0 : 1;
	const dark = colors.dark === 1;
	if (!FOLLOW_THEME || !t || !t.rgb) {
		colors.deep = hexToRgb(COLOR_DEEP);
		colors.hot = dark ? hexToRgb(COLOR_HOT) : mix3(hexToRgb(COLOR_HOT), hexToRgb(COLOR_DEEP), 0.25);
		colors.core = hexToRgb(COLOR_CORE);
		colors.rock = dark ? [0, 0, 0] : [0.35, 0.3, 0.28];
		return;
	}
	colors.deep = dark ? mix3(t.rgb.accent2, [0, 0, 0], 0.4) : t.rgb.accent2;
	colors.hot = t.rgb.accent;
	colors.core = dark ? mix3(t.rgb.accent, [1, 1, 1], 0.6) : t.rgb.accent3;
	colors.rock = dark ? mix3(t.rgb.background, [0, 0, 0], 0.7) : t.rgb.muted;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_drift', 'u_mouse', 'u_deep', 'u_hot', 'u_core', 'u_rock', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

function size() {
	canvas.width = Math.max(1, Math.round(w * RENDER_SCALE));
	canvas.height = Math.max(1, Math.round(h * RENDER_SCALE));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const k = dt * FLOW_SPEED * (reduced ? REDUCED_SPEED : 1);
	time = (time + k) % 2000;
	// The cursor leans the flow toward its side of the screen, easing back once it rests
	mouse.target = Math.max(0, mouse.target - dt * 0.4);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 2);
	const want = w ? (mouse.x / w - 0.5) * 2 * mouse.amount * CURSOR_HEAT : 0;
	mouse.lean += (want - mouse.lean) * Math.min(1, dt * 0.8);
	drift = (drift + k * (0.02 + mouse.lean * 0.06)) % 1000;
	const ease = Math.min(1, dt * 4);
	mouse.sx += (mouse.x - mouse.sx) * ease;
	mouse.sy += (mouse.y - mouse.sy) * ease;
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform1f(loc.u_drift, drift);
	gl.uniform3f(loc.u_mouse, mouse.sx, mouse.sy, mouse.amount);
	gl.uniform3fv(loc.u_deep, colors.deep);
	gl.uniform3fv(loc.u_hot, colors.hot);
	gl.uniform3fv(loc.u_core, colors.core);
	gl.uniform3fv(loc.u_rock, colors.rock);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Molten Forge: WebGL is not available, so the lava is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Molten Forge:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Molten Forge:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			time = Math.random() * 200;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			if (mouse.amount < 0.02) { mouse.sx = d.x; mouse.sy = d.y; }
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

dark.customCSS:
:root {
	--nta-glass: color-mix(in oklab, var(--color-gray-950) 72%, transparent);
	--nta-sidebar: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
	--nta-bubble: color-mix(in oklab, var(--color-gray-800) 58%, transparent);
	--nta-selected: color-mix(in oklab, var(--color-gray-700) 35%, transparent);
	--nta-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--nta-ring: color-mix(in oklab, #fa6e1d 24%, transparent);
	--nta-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--nta-orange: #fa6e1d;
	--nta-link: #ff8f4b;
	--nta-head: var(--color-gray-100);
}

/* Military console: slate surfaces, safety orange for focus, status and
   links, stenciled monospace headings. !important only where Canvas FX
   transparency clears a background. */
#message-input-container {
	background-color: var(--nta-glass) !important;
	border-color: var(--nta-line) !important;
	backdrop-filter: blur(16px);
	box-shadow: 0 12px 36px -18px var(--nta-shade);
	transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#message-input-container:focus-within {
	border-color: var(--nta-orange) !important;
	box-shadow: 0 0 0 3px var(--nta-ring), 0 12px 36px -18px var(--nta-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--nta-bubble) !important;
	backdrop-filter: blur(10px);
	box-shadow: inset 0 0 0 1px var(--nta-line);
}
#sidebar {
	background-color: var(--nta-sidebar) !important;
	backdrop-filter: blur(18px);
	border-inline-end: 1px solid var(--nta-line);
}
#sidebar-chat-item.selected {
	background-color: var(--nta-selected);
	box-shadow: inset 2px 0 0 var(--nta-orange);
}
.markdown-prose :is(h1, h2, h3) {
	color: var(--nta-head);
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
	text-transform: uppercase;
	letter-spacing: 0.08em;
}
.markdown-prose :is(h1, h2, h3)::before { content: "■ "; color: var(--nta-orange); }
.markdown-prose a { color: var(--nta-link); }
.markdown-prose blockquote { border-inline-start-color: var(--nta-orange); }
.markdown-prose hr { border-color: var(--nta-line); }
::selection { background-color: var(--nta-ring); }
html { scrollbar-color: var(--nta-line) transparent; }

dark.canvasScript:
/**
 * Title: Topographic Map
 * Description: Contour lines and soft elevation fills over slowly flowing terrain in your theme's colors, fading behind the chat column; the cursor raises a gentle hill that settles once it stops.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CONTOURS        = 14;      // contour levels (4-30)
const CONTOUR_OPACITY = 0.4;     // contour line opacity (0-1)
const LINE_WIDTH      = 1;       // contour line width, in px (0.5-3)
const FILL_OPACITY    = 0.16;    // elevation fill opacity; 0 draws lines only (0-0.5)
const MOTION          = 1;       // how fast the terrain flows; 0 holds it still (0-3)
const REDUCED_SPEED   = 0.15;    // share of the flow kept under reduced motion (0-1)
const NOISE_SCALE     = 0.0035;  // terrain feature size; lower is broader (0.001-0.01)
const OCTAVES         = 4;       // terrain detail layers (1-5)
const GRID_STEP       = 8;       // sampling cell, in px; larger is cheaper and smoother (5-14)
const MAX_FPS         = 20;      // redraws per second; the terrain moves slowly (10-60)
const HILL_RADIUS     = 200;     // radius of the cursor's hill, in px (0-400)
const HILL_HEIGHT     = 0.35;    // height of the cursor's hill (0-1)
const CENTER_CALM     = 0.8;     // how much lines and fills fade behind the chat column (0-1)
const BAND_WIDTH      = 520;     // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;    // draw in the theme's colors
const PALETTE         = ['#0a2463', '#1e6091', '#168aad', '#34a0a4', '#52b69a', '#76c893', '#99d98c', '#d9ed92', '#f0f3bd'];  // low to high when not following the theme
/* ──────────────────────────────────────────── */

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, drawn = 0, reduced = false, dark = true, column = null;
let cols = 1, rows = 1, grid = new Float32Array(1), calmCol = new Float32Array(1);
let fillCanvas, fillCtx, imageData, pixels;
let palette = PALETTE, alphaScale = 1, lutDirty = true, levelStyle = [];
let time = 0, minE = 0, maxE = 1;
const LUT = new Uint8Array(256 * 3);
const mouse = { x: -10000, y: -10000, amount: 0, hill: 0 };

// ── Gradient noise from a seeded permutation table ──
const PERM = new Uint8Array(512);
(function () {
	const p = new Uint8Array(256);
	for (let i = 0; i < 256; i++) p[i] = i;
	let seed = 42;
	for (let i = 255; i > 0; i--) {
		seed = (seed * 16807) % 2147483647;
		const j = seed % (i + 1), t = p[i];
		p[i] = p[j]; p[j] = t;
	}
	for (let i = 0; i < 512; i++) PERM[i] = p[i & 255];
})();
const GX = new Float32Array([1, -1, 1, -1, 1, 0, -1, 0]), GY = new Float32Array([1, 1, -1, -1, 0, 1, 0, -1]);

function noise(x, y) {
	const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
	const sx = fx * fx * fx * (fx * (fx * 6 - 15) + 10), sy = fy * fy * fy * (fy * (fy * 6 - 15) + 10);
	const a = ix & 255, b = iy & 255, a1 = (a + 1) & 255, b1 = (b + 1) & 255;
	const g00 = PERM[PERM[a] + b] & 7, g10 = PERM[PERM[a1] + b] & 7, g01 = PERM[PERM[a] + b1] & 7, g11 = PERM[PERM[a1] + b1] & 7;
	const n00 = GX[g00] * fx + GY[g00] * fy, n10 = GX[g10] * (fx - 1) + GY[g10] * fy;
	const n01 = GX[g01] * fx + GY[g01] * (fy - 1), n11 = GX[g11] * (fx - 1) + GY[g11] * (fy - 1);
	const nx0 = n00 + sx * (n10 - n00), nx1 = n01 + sx * (n11 - n01);
	return (nx0 + sy * (nx1 - nx0)) * 0.5 + 0.5;
}

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }

// Low to high: a quiet base, the three accents, then the text color at the peaks
function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	alphaScale = dark ? 1 : 0.75;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		palette = [dark ? c.surface : c.muted, c.accent3, c.accent, c.accent2, c.text];
	}
	lutDirty = true;
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The color LUT and one column-fading stroke style per contour level
function rebuildLUT() {
	lutDirty = false;
	const pal = palette.map(hex), n = pal.length;
	for (let i = 0; i < 256; i++) {
		const t = i / 255 * (n - 1), lo = Math.floor(t), hi = Math.min(lo + 1, n - 1), f = t - lo;
		for (let k = 0; k < 3; k++) LUT[i * 3 + k] = pal[lo][k] + (pal[hi][k] - pal[lo][k]) * f;
	}
	const a = CONTOUR_OPACITY * alphaScale, k = 1 - CENTER_CALM, m = colX() / Math.max(1, w), i0 = colHalf() * 0.55 / Math.max(1, w), o0 = colHalf() * 1.25 / Math.max(1, w);
	const at = (u) => Math.min(1, Math.max(0, u));
	for (let l = 0; l < CONTOURS; l++) {
		const ci = Math.round((l + 1) / (CONTOURS + 1) * 255) * 3;
		const rgb = LUT[ci] + ',' + LUT[ci + 1] + ',' + LUT[ci + 2] + ',';
		const g = ctx.createLinearGradient(0, 0, Math.max(1, w), 0);
		g.addColorStop(0, 'rgba(' + rgb + a + ')');
		g.addColorStop(at(m - o0), 'rgba(' + rgb + a + ')');
		g.addColorStop(at(m - i0), 'rgba(' + rgb + a * k + ')');
		g.addColorStop(at(m + i0), 'rgba(' + rgb + a * k + ')');
		g.addColorStop(at(m + o0), 'rgba(' + rgb + a + ')');
		g.addColorStop(1, 'rgba(' + rgb + a + ')');
		levelStyle[l] = g;
	}
}

// Each grid column's calm, from where the chat column sits; rebuilt on layout with the stroke styles
function calmBuild() {
	for (let c = 0; c < cols; c++) {
		const d = Math.abs(c * GRID_STEP - colX()) / colHalf(), t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
		calmCol[c] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	lutDirty = true;
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	cols = Math.max(2, Math.ceil(w / GRID_STEP) + 2);
	rows = Math.max(2, Math.ceil(h / GRID_STEP) + 2);
	grid = new Float32Array(cols * rows);
	calmCol = new Float32Array(cols);
	calmBuild();
	// The fill lives at one pixel per grid cell and is scaled up smoothly when drawn
	fillCanvas = new OffscreenCanvas(cols, rows);
	fillCtx = fillCanvas.getContext('2d');
	imageData = fillCtx.createImageData(cols, rows);
	pixels = imageData.data;
	lutDirty = true;
	drawn = 0;
}

function sample() {
	const tx = time * 0.25, ty = time * 0.18, drift = Math.sin(time * 0.4) * 0.3;
	const r2 = HILL_RADIUS * HILL_RADIUS, hill = HILL_HEIGHT * mouse.hill;
	let lo = Infinity, hi = -Infinity;
	for (let r = 0; r < rows; r++) {
		const py = r * GRID_STEP, off = r * cols;
		for (let c = 0; c < cols; c++) {
			const px = c * GRID_STEP;
			let x = px * NOISE_SCALE + tx + drift, y = py * NOISE_SCALE + ty - drift * 0.7, e = 0, amp = 0.5;
			for (let o = 0; o < OCTAVES; o++) { e += amp * noise(x, y); x *= 2; y *= 2; amp *= 0.5; }
			if (hill > 0.001) {
				const dx = px - mouse.x, dy = py - mouse.y, d2 = dx * dx + dy * dy;
				if (d2 < r2) { const f = 1 - Math.sqrt(d2) / HILL_RADIUS; e += hill * f * f * (3 - 2 * f); }
			}
			grid[off + c] = e;
			if (e < lo) lo = e;
			if (e > hi) hi = e;
		}
	}
	// Ease the range so contours do not jump when the hill rises
	if (!drawn) { minE = lo; maxE = hi; }
	minE += (lo - minE) * 0.2;
	maxE += (hi - maxE) * 0.2;
}

function drawFill() {
	const inv = 255 / (maxE - minE || 1), a = FILL_OPACITY * alphaScale * 255;
	for (let r = 0; r < rows; r++) {
		const off = r * cols;
		for (let c = 0; c < cols; c++) {
			const ci = Math.max(0, Math.min(255, ((grid[off + c] - minE) * inv) | 0)) * 3, p = (off + c) << 2;
			pixels[p] = LUT[ci]; pixels[p + 1] = LUT[ci + 1]; pixels[p + 2] = LUT[ci + 2];
			pixels[p + 3] = a * calmCol[c];
		}
	}
	fillCtx.putImageData(imageData, 0, 0);
	ctx.imageSmoothingEnabled = true;
	ctx.drawImage(fillCanvas, 0, 0, cols, rows, 0, 0, cols * GRID_STEP, rows * GRID_STEP);
}

// Marching squares, one path per level, saddles resolved by the cell's centre value
function drawContours() {
	const s = GRID_STEP, range = maxE - minE || 1;
	ctx.lineWidth = LINE_WIDTH;
	ctx.lineJoin = 'round';
	for (let l = 0; l < CONTOURS; l++) {
		const thr = minE + (l + 1) * range / (CONTOURS + 1);
		ctx.strokeStyle = levelStyle[l];
		ctx.beginPath();
		for (let r = 0; r < rows - 1; r++) {
			const o0 = r * cols, o1 = o0 + cols, y = r * s;
			for (let c = 0; c < cols - 1; c++) {
				const a = grid[o0 + c] - thr, b = grid[o0 + c + 1] - thr, d = grid[o1 + c + 1] - thr, e = grid[o1 + c] - thr;
				const code = (a > 0 ? 8 : 0) | (b > 0 ? 4 : 0) | (d > 0 ? 2 : 0) | (e > 0 ? 1 : 0);
				if (code === 0 || code === 15) continue;
				const x = c * s;
				const tX = x + a / (a - b) * s, rY = y + b / (b - d) * s, bX = x + e / (e - d) * s, lY = y + a / (a - e) * s;
				switch (code) {
					case 1: case 14: ctx.moveTo(x, lY); ctx.lineTo(bX, y + s); break;
					case 2: case 13: ctx.moveTo(bX, y + s); ctx.lineTo(x + s, rY); break;
					case 3: case 12: ctx.moveTo(x, lY); ctx.lineTo(x + s, rY); break;
					case 4: case 11: ctx.moveTo(tX, y); ctx.lineTo(x + s, rY); break;
					case 6: case 9: ctx.moveTo(tX, y); ctx.lineTo(bX, y + s); break;
					case 7: case 8: ctx.moveTo(x, lY); ctx.lineTo(tX, y); break;
					case 5: case 10: {
						const centre = (a + b + d + e) * 0.25;
						if ((centre > 0) === (a > 0)) {
							ctx.moveTo(tX, y); ctx.lineTo(x + s, rY);
							ctx.moveTo(x, lY); ctx.lineTo(bX, y + s);
						} else {
							ctx.moveTo(x, lY); ctx.lineTo(tX, y);
							ctx.moveTo(bX, y + s); ctx.lineTo(x + s, rY);
						}
						break;
					}
				}
			}
		}
		ctx.stroke();
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!w || !h) return;
	if (drawn && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * 0.36 * MOTION * (reduced ? REDUCED_SPEED : 1)) % 2000;
	mouse.amount = Math.max(0, mouse.amount - dt * 0.4);
	mouse.hill += (mouse.amount - mouse.hill) * Math.min(1, dt * (reduced ? 0.8 : 3));
	if (lutDirty) rebuildLUT();
	sample();
	ctx.clearRect(0, 0, w, h);
	if (FILL_OPACITY > 0) drawFill();
	drawContours();
	drawn++;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) calmBuild();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
	}
};

oled.customCSS:
:root {
	--nta-glass: color-mix(in oklab, var(--color-gray-950) 72%, transparent);
	--nta-sidebar: color-mix(in oklab, var(--color-gray-950) 80%, transparent);
	--nta-bubble: color-mix(in oklab, var(--color-gray-800) 58%, transparent);
	--nta-selected: color-mix(in oklab, var(--color-gray-700) 35%, transparent);
	--nta-line: color-mix(in oklab, var(--color-gray-400) 22%, transparent);
	--nta-ring: color-mix(in oklab, #fa6e1d 24%, transparent);
	--nta-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--nta-orange: #fa6e1d;
	--nta-link: #ff8f4b;
	--nta-head: var(--color-gray-100);
}

/* Military console: slate surfaces, safety orange for focus, status and
   links, stenciled monospace headings. !important only where Canvas FX
   transparency clears a background. */
#message-input-container {
	background-color: var(--nta-glass) !important;
	border-color: var(--nta-line) !important;
	backdrop-filter: blur(16px);
	box-shadow: 0 12px 36px -18px var(--nta-shade);
	transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#message-input-container:focus-within {
	border-color: var(--nta-orange) !important;
	box-shadow: 0 0 0 3px var(--nta-ring), 0 12px 36px -18px var(--nta-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--nta-bubble) !important;
	backdrop-filter: blur(10px);
	box-shadow: inset 0 0 0 1px var(--nta-line);
}
#sidebar {
	background-color: var(--nta-sidebar) !important;
	backdrop-filter: blur(18px);
	border-inline-end: 1px solid var(--nta-line);
}
#sidebar-chat-item.selected {
	background-color: var(--nta-selected);
	box-shadow: inset 2px 0 0 var(--nta-orange);
}
.markdown-prose :is(h1, h2, h3) {
	color: var(--nta-head);
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
	text-transform: uppercase;
	letter-spacing: 0.08em;
}
.markdown-prose :is(h1, h2, h3)::before { content: "■ "; color: var(--nta-orange); }
.markdown-prose a { color: var(--nta-link); }
.markdown-prose blockquote { border-inline-start-color: var(--nta-orange); }
.markdown-prose hr { border-color: var(--nta-line); }
::selection { background-color: var(--nta-ring); }
html { scrollbar-color: var(--nta-line) transparent; }

oled.canvasScript:
/**
 * Title: Topographic Map
 * Description: Contour lines and soft elevation fills over slowly flowing terrain in your theme's colors, fading behind the chat column; the cursor raises a gentle hill that settles once it stops.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CONTOURS        = 14;      // contour levels (4-30)
const CONTOUR_OPACITY = 0.4;     // contour line opacity (0-1)
const LINE_WIDTH      = 1;       // contour line width, in px (0.5-3)
const FILL_OPACITY    = 0.16;    // elevation fill opacity; 0 draws lines only (0-0.5)
const MOTION          = 1;       // how fast the terrain flows; 0 holds it still (0-3)
const REDUCED_SPEED   = 0.15;    // share of the flow kept under reduced motion (0-1)
const NOISE_SCALE     = 0.0035;  // terrain feature size; lower is broader (0.001-0.01)
const OCTAVES         = 4;       // terrain detail layers (1-5)
const GRID_STEP       = 8;       // sampling cell, in px; larger is cheaper and smoother (5-14)
const MAX_FPS         = 20;      // redraws per second; the terrain moves slowly (10-60)
const HILL_RADIUS     = 200;     // radius of the cursor's hill, in px (0-400)
const HILL_HEIGHT     = 0.35;    // height of the cursor's hill (0-1)
const CENTER_CALM     = 0.8;     // how much lines and fills fade behind the chat column (0-1)
const BAND_WIDTH      = 520;     // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME    = true;    // draw in the theme's colors
const PALETTE         = ['#0a2463', '#1e6091', '#168aad', '#34a0a4', '#52b69a', '#76c893', '#99d98c', '#d9ed92', '#f0f3bd'];  // low to high when not following the theme
/* ──────────────────────────────────────────── */

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, drawn = 0, reduced = false, dark = true, column = null;
let cols = 1, rows = 1, grid = new Float32Array(1), calmCol = new Float32Array(1);
let fillCanvas, fillCtx, imageData, pixels;
let palette = PALETTE, alphaScale = 1, lutDirty = true, levelStyle = [];
let time = 0, minE = 0, maxE = 1;
const LUT = new Uint8Array(256 * 3);
const mouse = { x: -10000, y: -10000, amount: 0, hill: 0 };

// ── Gradient noise from a seeded permutation table ──
const PERM = new Uint8Array(512);
(function () {
	const p = new Uint8Array(256);
	for (let i = 0; i < 256; i++) p[i] = i;
	let seed = 42;
	for (let i = 255; i > 0; i--) {
		seed = (seed * 16807) % 2147483647;
		const j = seed % (i + 1), t = p[i];
		p[i] = p[j]; p[j] = t;
	}
	for (let i = 0; i < 512; i++) PERM[i] = p[i & 255];
})();
const GX = new Float32Array([1, -1, 1, -1, 1, 0, -1, 0]), GY = new Float32Array([1, 1, -1, -1, 0, 1, 0, -1]);

function noise(x, y) {
	const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
	const sx = fx * fx * fx * (fx * (fx * 6 - 15) + 10), sy = fy * fy * fy * (fy * (fy * 6 - 15) + 10);
	const a = ix & 255, b = iy & 255, a1 = (a + 1) & 255, b1 = (b + 1) & 255;
	const g00 = PERM[PERM[a] + b] & 7, g10 = PERM[PERM[a1] + b] & 7, g01 = PERM[PERM[a] + b1] & 7, g11 = PERM[PERM[a1] + b1] & 7;
	const n00 = GX[g00] * fx + GY[g00] * fy, n10 = GX[g10] * (fx - 1) + GY[g10] * fy;
	const n01 = GX[g01] * fx + GY[g01] * (fy - 1), n11 = GX[g11] * (fx - 1) + GY[g11] * (fy - 1);
	const nx0 = n00 + sx * (n10 - n00), nx1 = n01 + sx * (n11 - n01);
	return (nx0 + sy * (nx1 - nx0)) * 0.5 + 0.5;
}

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }

// Low to high: a quiet base, the three accents, then the text color at the peaks
function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	alphaScale = dark ? 1 : 0.75;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		palette = [dark ? c.surface : c.muted, c.accent3, c.accent, c.accent2, c.text];
	}
	lutDirty = true;
}

// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

// The color LUT and one column-fading stroke style per contour level
function rebuildLUT() {
	lutDirty = false;
	const pal = palette.map(hex), n = pal.length;
	for (let i = 0; i < 256; i++) {
		const t = i / 255 * (n - 1), lo = Math.floor(t), hi = Math.min(lo + 1, n - 1), f = t - lo;
		for (let k = 0; k < 3; k++) LUT[i * 3 + k] = pal[lo][k] + (pal[hi][k] - pal[lo][k]) * f;
	}
	const a = CONTOUR_OPACITY * alphaScale, k = 1 - CENTER_CALM, m = colX() / Math.max(1, w), i0 = colHalf() * 0.55 / Math.max(1, w), o0 = colHalf() * 1.25 / Math.max(1, w);
	const at = (u) => Math.min(1, Math.max(0, u));
	for (let l = 0; l < CONTOURS; l++) {
		const ci = Math.round((l + 1) / (CONTOURS + 1) * 255) * 3;
		const rgb = LUT[ci] + ',' + LUT[ci + 1] + ',' + LUT[ci + 2] + ',';
		const g = ctx.createLinearGradient(0, 0, Math.max(1, w), 0);
		g.addColorStop(0, 'rgba(' + rgb + a + ')');
		g.addColorStop(at(m - o0), 'rgba(' + rgb + a + ')');
		g.addColorStop(at(m - i0), 'rgba(' + rgb + a * k + ')');
		g.addColorStop(at(m + i0), 'rgba(' + rgb + a * k + ')');
		g.addColorStop(at(m + o0), 'rgba(' + rgb + a + ')');
		g.addColorStop(1, 'rgba(' + rgb + a + ')');
		levelStyle[l] = g;
	}
}

// Each grid column's calm, from where the chat column sits; rebuilt on layout with the stroke styles
function calmBuild() {
	for (let c = 0; c < cols; c++) {
		const d = Math.abs(c * GRID_STEP - colX()) / colHalf(), t = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
		calmCol[c] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	lutDirty = true;
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	cols = Math.max(2, Math.ceil(w / GRID_STEP) + 2);
	rows = Math.max(2, Math.ceil(h / GRID_STEP) + 2);
	grid = new Float32Array(cols * rows);
	calmCol = new Float32Array(cols);
	calmBuild();
	// The fill lives at one pixel per grid cell and is scaled up smoothly when drawn
	fillCanvas = new OffscreenCanvas(cols, rows);
	fillCtx = fillCanvas.getContext('2d');
	imageData = fillCtx.createImageData(cols, rows);
	pixels = imageData.data;
	lutDirty = true;
	drawn = 0;
}

function sample() {
	const tx = time * 0.25, ty = time * 0.18, drift = Math.sin(time * 0.4) * 0.3;
	const r2 = HILL_RADIUS * HILL_RADIUS, hill = HILL_HEIGHT * mouse.hill;
	let lo = Infinity, hi = -Infinity;
	for (let r = 0; r < rows; r++) {
		const py = r * GRID_STEP, off = r * cols;
		for (let c = 0; c < cols; c++) {
			const px = c * GRID_STEP;
			let x = px * NOISE_SCALE + tx + drift, y = py * NOISE_SCALE + ty - drift * 0.7, e = 0, amp = 0.5;
			for (let o = 0; o < OCTAVES; o++) { e += amp * noise(x, y); x *= 2; y *= 2; amp *= 0.5; }
			if (hill > 0.001) {
				const dx = px - mouse.x, dy = py - mouse.y, d2 = dx * dx + dy * dy;
				if (d2 < r2) { const f = 1 - Math.sqrt(d2) / HILL_RADIUS; e += hill * f * f * (3 - 2 * f); }
			}
			grid[off + c] = e;
			if (e < lo) lo = e;
			if (e > hi) hi = e;
		}
	}
	// Ease the range so contours do not jump when the hill rises
	if (!drawn) { minE = lo; maxE = hi; }
	minE += (lo - minE) * 0.2;
	maxE += (hi - maxE) * 0.2;
}

function drawFill() {
	const inv = 255 / (maxE - minE || 1), a = FILL_OPACITY * alphaScale * 255;
	for (let r = 0; r < rows; r++) {
		const off = r * cols;
		for (let c = 0; c < cols; c++) {
			const ci = Math.max(0, Math.min(255, ((grid[off + c] - minE) * inv) | 0)) * 3, p = (off + c) << 2;
			pixels[p] = LUT[ci]; pixels[p + 1] = LUT[ci + 1]; pixels[p + 2] = LUT[ci + 2];
			pixels[p + 3] = a * calmCol[c];
		}
	}
	fillCtx.putImageData(imageData, 0, 0);
	ctx.imageSmoothingEnabled = true;
	ctx.drawImage(fillCanvas, 0, 0, cols, rows, 0, 0, cols * GRID_STEP, rows * GRID_STEP);
}

// Marching squares, one path per level, saddles resolved by the cell's centre value
function drawContours() {
	const s = GRID_STEP, range = maxE - minE || 1;
	ctx.lineWidth = LINE_WIDTH;
	ctx.lineJoin = 'round';
	for (let l = 0; l < CONTOURS; l++) {
		const thr = minE + (l + 1) * range / (CONTOURS + 1);
		ctx.strokeStyle = levelStyle[l];
		ctx.beginPath();
		for (let r = 0; r < rows - 1; r++) {
			const o0 = r * cols, o1 = o0 + cols, y = r * s;
			for (let c = 0; c < cols - 1; c++) {
				const a = grid[o0 + c] - thr, b = grid[o0 + c + 1] - thr, d = grid[o1 + c + 1] - thr, e = grid[o1 + c] - thr;
				const code = (a > 0 ? 8 : 0) | (b > 0 ? 4 : 0) | (d > 0 ? 2 : 0) | (e > 0 ? 1 : 0);
				if (code === 0 || code === 15) continue;
				const x = c * s;
				const tX = x + a / (a - b) * s, rY = y + b / (b - d) * s, bX = x + e / (e - d) * s, lY = y + a / (a - e) * s;
				switch (code) {
					case 1: case 14: ctx.moveTo(x, lY); ctx.lineTo(bX, y + s); break;
					case 2: case 13: ctx.moveTo(bX, y + s); ctx.lineTo(x + s, rY); break;
					case 3: case 12: ctx.moveTo(x, lY); ctx.lineTo(x + s, rY); break;
					case 4: case 11: ctx.moveTo(tX, y); ctx.lineTo(x + s, rY); break;
					case 6: case 9: ctx.moveTo(tX, y); ctx.lineTo(bX, y + s); break;
					case 7: case 8: ctx.moveTo(x, lY); ctx.lineTo(tX, y); break;
					case 5: case 10: {
						const centre = (a + b + d + e) * 0.25;
						if ((centre > 0) === (a > 0)) {
							ctx.moveTo(tX, y); ctx.lineTo(x + s, rY);
							ctx.moveTo(x, lY); ctx.lineTo(bX, y + s);
						} else {
							ctx.moveTo(x, lY); ctx.lineTo(tX, y);
							ctx.moveTo(bX, y + s); ctx.lineTo(x + s, rY);
						}
						break;
					}
				}
			}
		}
		ctx.stroke();
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!w || !h) return;
	if (drawn && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * 0.36 * MOTION * (reduced ? REDUCED_SPEED : 1)) % 2000;
	mouse.amount = Math.max(0, mouse.amount - dt * 0.4);
	mouse.hill += (mouse.amount - mouse.hill) * Math.min(1, dt * (reduced ? 0.8 : 3));
	if (lutDirty) rebuildLUT();
	sample();
	ctx.clearRect(0, 0, w, h);
	if (FILL_OPACITY > 0) drawFill();
	drawContours();
	drawn++;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) calmBuild();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
	}
};

