:root {
	--nta-glass: color-mix(in oklab, var(--color-gray-50) 78%, transparent);
	--nta-sidebar: color-mix(in oklab, var(--color-gray-100) 80%, transparent);
	--nta-bubble: color-mix(in oklab, var(--color-gray-200) 62%, transparent);
