	--nta-line: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--nta-ring: color-mix(in oklab, #d54d1d 22%, transparent);
	--nta-shade: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
	--nta-orange: #d54d1d;
	--nta-link: #ab3511;
	--nta-head: var(--color-gray-900);
}

