	backdrop-filter: blur(16px);
	box-shadow: 0 12px 36px -18px var(--nta-shade);
	transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#message-input-container:focus-within {
	border-color: var(--nta-orange) !important;
	box-shadow: 0 0 0 3px var(--nta-ring), 0 12px 36px -18px var(--nta-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--nta-bubble) !important;
	backdrop-filter: blur(10px);
	box-shadow: inset 0 0 0 1px var(--nta-line);
}
#sidebar {
	background-color: var(--nta-sidebar) !important;
	backdrop-filter: blur(18px);
	border-inline-end: 1px solid var(--nta-line);
}
