			// A tap warms the blobs nearby, so they start to rise
			for (let i = 0; i < N; i++) {
				const dx = bx[i] - d.x, dy = by[i] - d.y;
				if (dx * dx + dy * dy < 220 * 220) temp[i] = Math.min(1, temp[i] + (reduced ? 0.1 : 0.35));
			}
			break;
	}
};

