			const dx = ex[i] - mouse.x, dy = ey[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < 32400 && dd > 1) {
				const dist = Math.sqrt(dd);
				evx[i] += (dx / dist) * (1 - dist / 180) * wind * dt;
				ey[i] -= (1 - dist / 180) * wind * 0.15 * dt;
			}
		}
		evx[i] *= drag;
		ex[i] += (evx[i] + Math.sin(time * 0.8 + eph[i]) * SWAY) * dt;
		if (ex[i] < -20) ex[i] += w + 40; else if (ex[i] > w + 20) ex[i] -= w + 40;
		const a = Math.min(1, eage[i] / 0.8) * (1 - r * r) * (0.7 + 0.3 * Math.sin(time * 3 + eph[i] * 5)) * calm(ex[i]) * lit;
		if (a < 0.02) continue;
		const d = esz[i] * (1 - r * 0.5);
		ctx.globalAlpha = a;
		ctx.drawImage(emberSprites[r < 0.3 ? 0 : r < 0.65 ? 1 : 2], ex[i] - d / 2, ey[i] - d / 2, d, d);
	}

	// Tap bursts
	const grav = 60 * dt;
	for (let i = 0; i < bcount; i++) {
		blife[i] -= dt;
		if (blife[i] <= 0) {
			const j = --bcount;
			bx[i] = bx[j]; by[i] = by[j]; bvx[i] = bvx[j]; bvy[i] = bvy[j]; blife[i] = blife[j]; bsz[i] = bsz[j];
			i--;
			continue;
		}
		bvx[i] *= drag; bvy[i] = bvy[i] * drag + grav;
		bx[i] += bvx[i] * dt; by[i] += bvy[i] * dt;
		const f = Math.min(1, blife[i] / 1.2);
		ctx.globalAlpha = f * lit * Math.max(0.35, calm(bx[i]));
		const d = bsz[i] * (0.6 + 0.4 * f);
		ctx.drawImage(emberSprites[f > 0.6 ? 0 : 1], bx[i] - d / 2, by[i] - d / 2, d, d);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

function move(x, y) {
	if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(x - mouse.x, y - mouse.y) / 60);
	mouse.x = x; mouse.y = y;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) buildCalm();
			break;
		case 'mousemove':
			move(d.x, d.y);
			break;
		case 'touchmove':
			if (d.touches && d.touches.length) move(d.touches[0].x, d.touches[0].y);
			break;
		case 'mousedown':
			if (!reduced && BURST_SIZE > 0) burst(d.x, d.y);
			break;
	}
};

her.customCSS:
:root {
	--sol-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--sol-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--sol-bubble: color-mix(in oklab, var(--sol-accent) 10%, var(--color-gray-100) 58%);
	--sol-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--sol-line: color-mix(in oklab, var(--sol-accent) 32%, transparent);
	--sol-glow: color-mix(in oklab, var(--sol-accent) 50%, transparent);
	--sol-ring: color-mix(in oklab, var(--sol-accent) 18%, transparent);
	--sol-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--sol-accent: oklch(0.52 0.11 42);
}

/* Warm glass edged with a gold hairline, in Open WebUI's own shapes. Colors come from the palette; !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--sol-glass) !important;
	border-color: var(--sol-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--sol-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--sol-glow) !important;
	box-shadow: 0 0 0 3px var(--sol-ring), 0 12px 40px -16px var(--sol-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--sol-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--sol-line);
}
#sidebar {
	background-color: var(--sol-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--sol-line);
}
#sidebar-chat-item.selected { background-color: var(--sol-selected); }
.markdown-prose a { color: var(--sol-accent); text-decoration-color: var(--sol-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--sol-glow); }
.markdown-prose :is(h1, h2) { color: var(--sol-accent); letter-spacing: 0.01em; }
.markdown-prose hr { border: 0; height: 1px; background: linear-gradient(90deg, transparent, var(--sol-glow), transparent); }
html { scrollbar-color: var(--sol-line) transparent; }
::selection { background-color: var(--sol-ring); }

