const EDGE_COLOR    = '#8c95b0';  // leading color
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_edge;',
	'uniform vec3 u_core;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'vec2 hash2(vec2 p) { p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3))); return fract(sin(p) * 43758.5453); }',
	'float hash(vec2 p) { return fract(sin(dot(p, vec2(41.3, 289.1))) * 45758.5453); }',
	// x: nearest distance, y: second nearest, z: cell id, w: distance to the seed
	'vec4 voronoi(vec2 p, float t) {',
	'	vec2 ip = floor(p), fp = fract(p);',
	'	float d1 = 8.0, d2 = 8.0, id = 0.0;',
	'	for (int j = -1; j <= 1; j++) {',
	'		for (int i = -1; i <= 1; i++) {',
	'			vec2 nb = vec2(float(i), float(j));',
	'			vec2 o = hash2(ip + nb);',
	'			vec2 orbit = 0.32 * vec2(sin(t * (0.8 + o.x * 0.6) + o.y * 6.2831), cos(t * (0.6 + o.y * 0.8) + o.x * 6.2831));',
	'			vec2 s = nb + 0.5 + (o - 0.5) * 0.5 + orbit - fp;',
	'			float d = dot(s, s);',
	'			if (d < d1) { d2 = d1; d1 = d; id = hash(ip + nb); }',
	'			else if (d < d2) { d2 = d; }',
	'		}',
	'	}',
	'	d1 = sqrt(d1);',
	'	return vec4(d1, sqrt(d2), id, d1);',
	'}',
	// A cyclic blend through the three accents, so each pane's tint wanders smoothly
	'vec3 tint(float h) {',
	'	h = fract(h) * 3.0;',
	'	if (h < 1.0) return mix(u_c1, u_c2, smoothstep(0.0, 1.0, h));',
	'	if (h < 2.0) return mix(u_c2, u_c3, smoothstep(1.0, 2.0, h));',
	'	return mix(u_c3, u_c1, smoothstep(2.0, 3.0, h));',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	float t = u_time;',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float flash = u_mouse.z * ' + FLASHLIGHT.toFixed(3) + ' * smoothstep(' + FLASH_RADIUS.toFixed(1) + ', 0.0, length(px - m));',
	'	vec2 uv = px / res.y * ' + CELLS.toFixed(3) + ';',
	'	float ew = 0.022 * ' + EDGE_WIDTH.toFixed(3) + ' * (1.0 + flash * 1.2);',
	// Front layer: tinted panes with faceted shading and glowing leading
	'	vec4 v = voronoi(uv, t);',
	'	float gap = v.y - v.x;',
	'	float lead = 1.0 - smoothstep(ew * 0.4, ew, gap);',
	'	float halo = exp(-gap / (ew * 3.5)) * (1.0 - lead);',
	'	float hue = v.z + t * 0.05 * ' + HUE_DRIFT.toFixed(3) + ';',
	'	vec3 pane = tint(hue);',
	'	float facet = 0.35 + 0.65 * smoothstep(0.75, 0.0, v.w);',
	'	float shimmer = 0.75 + 0.25 * sin(v.z * 17.3 + t * 0.6);',
	'	float paneA = ' + CELL_FILL.toFixed(3) + ' * 0.5 * facet * shimmer * (1.0 + flash * 1.2) * mix(1.5, 1.0, u_dark);',
	'	vec3 leadCol = mix(u_edge, tint(hue + 0.33), 0.5);',
	'	leadCol = mix(leadCol, u_core, flash * 0.6 * u_dark);',
	'	float leadA = ' + EDGE_GLOW.toFixed(3) + ' * (lead * 0.7 + halo * 0.22) * (1.0 + flash * 1.5);',
	// Back layer: larger, slower panes for depth
	'	vec4 b = voronoi(uv * 0.42 + vec2(17.3, 5.1), t * 0.6);',
	'	float gap2 = b.y - b.x;',
	'	float lead2 = 1.0 - smoothstep(ew * 0.3, ew * 0.9, gap2);',
	'	vec3 pane2 = tint(b.z + 0.5 + t * 0.03 * ' + HUE_DRIFT.toFixed(3) + ');',
	'	float back = ' + DEPTH_LAYER.toFixed(3) + ';',
	'	float pane2A = back * 0.22 * (0.5 + 0.5 * smoothstep(0.9, 0.0, b.w));',
	'	float lead2A = back * lead2 * 0.3 * ' + EDGE_GLOW.toFixed(3) + ';',
	// Fade behind the chat column (center and half-width in u_col), gather away from it
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float edgeBias = 0.65 + 0.35 * smoothstep(0.15, 0.7, length((px - vec2(u_col.x, res.y * 0.5)) / res));',
	'	float k = calm * edgeBias * mix(0.8, 1.0, u_dark);',
	// Premultiplied composite: back layer, panes, then leading on top
	'	vec3 col = pane2 * pane2A + u_edge * lead2A;',
	'	float a = pane2A + lead2A * (1.0 - pane2A);',
	'	col = pane * paneA + col * (1.0 - paneA);',
	'	a = paneA + a * (1.0 - paneA);',
	'	leadA = clamp(leadA, 0.0, 0.9);',
	'	col = leadCol * leadA + col * (1.0 - leadA);',
	'	a = leadA + a * (1.0 - leadA);',
	'	a = clamp(a * k, 0.0, 1.0);',
	'	col *= k;',
	'	gl_FragColor = vec4(min(col, vec3(a)), a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
let loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const colors = { c1: hexToRgb(COLOR_A), c2: hexToRgb(COLOR_B), c3: hexToRgb(COLOR_C), edge: hexToRgb(EDGE_COLOR), core: [0.92, 0.95, 1], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent2;
	colors.c3 = t.rgb.accent3;
	colors.edge = t.rgb.muted;
	colors.core = t.rgb.text;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_mouse', 'u_c1', 'u_c2', 'u_c3', 'u_edge', 'u_core', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// The leading is line art, so a dense screen gets more pixels, never past full size
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function size() {
	const scale = Math.min(1, RENDER_SCALE * Math.min(dpr, 2));
	canvas.width = Math.max(1, Math.round(w * scale));
	canvas.height = Math.max(1, Math.round(h * scale));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * 0.25 * MOTION * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * (reduced ? 1.5 : 4));
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.x, mouse.y, mouse.amount);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_edge, colors.edge);
	gl.uniform3fv(loc.u_core, colors.core);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Voronoi Prism: WebGL is not available, so the glass is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Voronoi Prism:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Voronoi Prism:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

her.customCSS:
:root {
	--sov-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--sov-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--sov-bubble: color-mix(in oklab, var(--sov-accent) 6%, var(--color-gray-100) 58%);
	--sov-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--sov-line: color-mix(in oklab, var(--color-gray-500) 32%, transparent);
	--sov-glow: color-mix(in oklab, var(--sov-accent) 50%, transparent);
	--sov-ring: color-mix(in oklab, var(--sov-accent) 18%, transparent);
	--sov-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--sov-accent: oklch(0.47 0.09 292);
}

/* Navy glass with crisp hairlines, in Open WebUI's own shapes. Colors come from the palette; !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--sov-glass) !important;
	border-color: var(--sov-line) !important;
	backdrop-filter: blur(16px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--sov-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--sov-glow) !important;
	box-shadow: 0 0 0 3px var(--sov-ring), 0 12px 40px -16px var(--sov-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--sov-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--sov-line);
}
#sidebar {
	background-color: var(--sov-sidebar) !important;
	backdrop-filter: blur(20px) saturate(1.2);
	border-inline-end: 1px solid var(--sov-line);
}
#sidebar-chat-item.selected { background-color: var(--sov-selected); }
.markdown-prose a { color: var(--sov-accent); text-decoration-color: var(--sov-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--sov-glow); }
.markdown-prose :is(h1, h2, h3) { letter-spacing: 0.02em; }
.markdown-prose h2 { border-bottom: 1px solid var(--sov-line); padding-bottom: 0.25em; }
.markdown-prose :is(hr, th, td) { border-color: var(--sov-line); }
html { scrollbar-color: var(--sov-line) transparent; }
::selection { background-color: var(--sov-ring); }

her.canvasScript:
/**
 * Title: Voronoi Prism (WebGL)
 * Description: Two layers of drifting stained-glass Voronoi cells tinted with your theme's accents, fading behind the chat, with edges that flare under the cursor.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const CELLS         = 4;     // cells across the screen's height; higher is smaller glass (2-12)
const MOTION        = 0.5;     // how fast the seeds orbit; 0 holds the glass still (0-3)
const REDUCED_SPEED = 0.15;  // share of the motion kept when the viewer asks to reduce motion (0-1)
const CELL_FILL     = 0.35;   // how strongly the cell glass is tinted (0-1)
const EDGE_WIDTH    = 1.2;   // thickness of the leading between cells (0.4-3)
const EDGE_GLOW     = 0.55;   // brightness of the leading and its glow (0-1.5)
const DEPTH_LAYER   = 0.3;  // strength of the larger, slower layer behind (0-1)
const HUE_DRIFT     = 0.4;     // how quickly each cell's tint wanders between the accents (0-3)
const CENTER_CALM   = 0.85;   // how much the glass fades behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FLASHLIGHT    = 1;     // how much the cursor brightens cells and flares edges (0-2)
const FLASH_RADIUS  = 260;   // reach of the cursor's light, in px (80-600)
const RENDER_SCALE  = 0.75;  // resolution of the glass relative to the screen (0.4-1)
const MAX_FPS       = 30;    // frame cap; the glass moves slowly (15-60)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#5fb8e8';  // first glass tint when not following the theme
const COLOR_B       = '#b06ce0';  // second glass tint
const COLOR_C       = '#e8a24f';  // third glass tint
const EDGE_COLOR    = '#8c95b0';  // leading color
/* ──────────────────────────────────────────── */

const VERT = 'attribute vec2 a_pos; void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }';

const FRAG = [
	'#ifdef GL_FRAGMENT_PRECISION_HIGH',
	'precision highp float;',
	'#else',
	'precision mediump float;',
	'#endif',
	'uniform vec2 u_res;',
	'uniform float u_scale;',
	'uniform float u_time;',
	'uniform vec3 u_mouse;',
	'uniform vec3 u_c1;',
	'uniform vec3 u_c2;',
	'uniform vec3 u_c3;',
	'uniform vec3 u_edge;',
	'uniform vec3 u_core;',
	'uniform float u_dark;',
	'uniform vec2 u_col;',
	'vec2 hash2(vec2 p) { p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3))); return fract(sin(p) * 43758.5453); }',
	'float hash(vec2 p) { return fract(sin(dot(p, vec2(41.3, 289.1))) * 45758.5453); }',
	// x: nearest distance, y: second nearest, z: cell id, w: distance to the seed
	'vec4 voronoi(vec2 p, float t) {',
	'	vec2 ip = floor(p), fp = fract(p);',
	'	float d1 = 8.0, d2 = 8.0, id = 0.0;',
	'	for (int j = -1; j <= 1; j++) {',
	'		for (int i = -1; i <= 1; i++) {',
	'			vec2 nb = vec2(float(i), float(j));',
	'			vec2 o = hash2(ip + nb);',
	'			vec2 orbit = 0.32 * vec2(sin(t * (0.8 + o.x * 0.6) + o.y * 6.2831), cos(t * (0.6 + o.y * 0.8) + o.x * 6.2831));',
	'			vec2 s = nb + 0.5 + (o - 0.5) * 0.5 + orbit - fp;',
	'			float d = dot(s, s);',
	'			if (d < d1) { d2 = d1; d1 = d; id = hash(ip + nb); }',
	'			else if (d < d2) { d2 = d; }',
	'		}',
	'	}',
	'	d1 = sqrt(d1);',
	'	return vec4(d1, sqrt(d2), id, d1);',
	'}',
	// A cyclic blend through the three accents, so each pane's tint wanders smoothly
	'vec3 tint(float h) {',
	'	h = fract(h) * 3.0;',
	'	if (h < 1.0) return mix(u_c1, u_c2, smoothstep(0.0, 1.0, h));',
	'	if (h < 2.0) return mix(u_c2, u_c3, smoothstep(1.0, 2.0, h));',
	'	return mix(u_c3, u_c1, smoothstep(2.0, 3.0, h));',
	'}',
	'void main() {',
	'	vec2 px = gl_FragCoord.xy / u_scale;',
	'	vec2 res = u_res / u_scale;',
	'	float t = u_time;',
	'	vec2 m = vec2(u_mouse.x, res.y - u_mouse.y);',
	'	float flash = u_mouse.z * ' + FLASHLIGHT.toFixed(3) + ' * smoothstep(' + FLASH_RADIUS.toFixed(1) + ', 0.0, length(px - m));',
	'	vec2 uv = px / res.y * ' + CELLS.toFixed(3) + ';',
	'	float ew = 0.022 * ' + EDGE_WIDTH.toFixed(3) + ' * (1.0 + flash * 1.2);',
	// Front layer: tinted panes with faceted shading and glowing leading
	'	vec4 v = voronoi(uv, t);',
	'	float gap = v.y - v.x;',
	'	float lead = 1.0 - smoothstep(ew * 0.4, ew, gap);',
	'	float halo = exp(-gap / (ew * 3.5)) * (1.0 - lead);',
	'	float hue = v.z + t * 0.05 * ' + HUE_DRIFT.toFixed(3) + ';',
	'	vec3 pane = tint(hue);',
	'	float facet = 0.35 + 0.65 * smoothstep(0.75, 0.0, v.w);',
	'	float shimmer = 0.75 + 0.25 * sin(v.z * 17.3 + t * 0.6);',
	'	float paneA = ' + CELL_FILL.toFixed(3) + ' * 0.5 * facet * shimmer * (1.0 + flash * 1.2) * mix(1.5, 1.0, u_dark);',
	'	vec3 leadCol = mix(u_edge, tint(hue + 0.33), 0.5);',
	'	leadCol = mix(leadCol, u_core, flash * 0.6 * u_dark);',
	'	float leadA = ' + EDGE_GLOW.toFixed(3) + ' * (lead * 0.7 + halo * 0.22) * (1.0 + flash * 1.5);',
	// Back layer: larger, slower panes for depth
	'	vec4 b = voronoi(uv * 0.42 + vec2(17.3, 5.1), t * 0.6);',
	'	float gap2 = b.y - b.x;',
	'	float lead2 = 1.0 - smoothstep(ew * 0.3, ew * 0.9, gap2);',
	'	vec3 pane2 = tint(b.z + 0.5 + t * 0.03 * ' + HUE_DRIFT.toFixed(3) + ');',
	'	float back = ' + DEPTH_LAYER.toFixed(3) + ';',
	'	float pane2A = back * 0.22 * (0.5 + 0.5 * smoothstep(0.9, 0.0, b.w));',
	'	float lead2A = back * lead2 * 0.3 * ' + EDGE_GLOW.toFixed(3) + ';',
	// Fade behind the chat column (center and half-width in u_col), gather away from it
	'	float band = abs(px.x - u_col.x) / u_col.y;',
	'	float calm = 1.0 - ' + CENTER_CALM.toFixed(3) + ' * (1.0 - smoothstep(0.55, 1.25, band));',
	'	float edgeBias = 0.65 + 0.35 * smoothstep(0.15, 0.7, length((px - vec2(u_col.x, res.y * 0.5)) / res));',
	'	float k = calm * edgeBias * mix(0.8, 1.0, u_dark);',
	// Premultiplied composite: back layer, panes, then leading on top
	'	vec3 col = pane2 * pane2A + u_edge * lead2A;',
	'	float a = pane2A + lead2A * (1.0 - pane2A);',
	'	col = pane * paneA + col * (1.0 - paneA);',
	'	a = paneA + a * (1.0 - paneA);',
	'	leadA = clamp(leadA, 0.0, 0.9);',
	'	col = leadCol * leadA + col * (1.0 - leadA);',
	'	a = leadA + a * (1.0 - leadA);',
	'	a = clamp(a * k, 0.0, 1.0);',
	'	col *= k;',
	'	gl_FragColor = vec4(min(col, vec3(a)), a);',
	'}',
].join('\n');

let canvas, gl, program, buffer;
let loc = {};
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, column = null;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const colors = { c1: hexToRgb(COLOR_A), c2: hexToRgb(COLOR_B), c3: hexToRgb(COLOR_C), edge: hexToRgb(EDGE_COLOR), core: [0.92, 0.95, 1], dark: 1 };

function hexToRgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function applyTheme(t) {
	if (!t) return;
	colors.dark = t.dark === false ? 0 : 1;
	if (!FOLLOW_THEME || !t.rgb) return;
	colors.c1 = t.rgb.accent;
	colors.c2 = t.rgb.accent2;
	colors.c3 = t.rgb.accent3;
	colors.edge = t.rgb.muted;
	colors.core = t.rgb.text;
}

function compile(type, source) {
	const shader = gl.createShader(type);
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
	return shader;
}

function setup() {
	program = gl.createProgram();
	gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
	gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
	gl.bindAttribLocation(program, 0, 'a_pos');
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
	gl.useProgram(program);
	buffer = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
	['u_res', 'u_scale', 'u_time', 'u_mouse', 'u_c1', 'u_c2', 'u_c3', 'u_edge', 'u_core', 'u_dark', 'u_col'].forEach((name) => {
		loc[name] = gl.getUniformLocation(program, name);
	});
	gl.disable(gl.BLEND);
	size();
}

// The leading is line art, so a dense screen gets more pixels, never past full size
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }

function size() {
	const scale = Math.min(1, RENDER_SCALE * Math.min(dpr, 2));
	canvas.width = Math.max(1, Math.round(w * scale));
	canvas.height = Math.max(1, Math.round(h * scale));
	if (gl && !gl.isContextLost()) gl.viewport(0, 0, canvas.width, canvas.height);
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!program || gl.isContextLost()) return;
	if (last && now - last < 1000 / MAX_FPS - 2) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time = (time + dt * 0.25 * MOTION * (reduced ? REDUCED_SPEED : 1)) % 3000;
	mouse.target = Math.max(0, mouse.target - dt * 0.35);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * (reduced ? 1.5 : 4));
	gl.uniform2f(loc.u_res, canvas.width, canvas.height);
	gl.uniform1f(loc.u_scale, canvas.width / Math.max(1, w));
	gl.uniform1f(loc.u_time, time);
	gl.uniform3f(loc.u_mouse, mouse.x, mouse.y, mouse.amount);
	gl.uniform3fv(loc.u_c1, colors.c1);
	gl.uniform3fv(loc.u_c2, colors.c2);
	gl.uniform3fv(loc.u_c3, colors.c3);
	gl.uniform3fv(loc.u_edge, colors.edge);
	gl.uniform3fv(loc.u_core, colors.core);
	gl.uniform1f(loc.u_dark, colors.dark);
	gl.uniform2f(loc.u_col, colX(), colHalf());
	gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function start() {
	const opts = { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false, powerPreference: 'low-power' };
	gl = canvas.getContext('webgl2', opts) || canvas.getContext('webgl', opts);
	if (!gl) {
		console.warn('Voronoi Prism: WebGL is not available, so the glass is not drawn.');
		return;
	}
	canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); program = null; });
	canvas.addEventListener('webglcontextrestored', () => {
		try { setup(); } catch (err) { console.error('Voronoi Prism:', err.message); }
	});
	try {
		setup();
		requestAnimationFrame(frame);
	} catch (err) {
		console.error('Voronoi Prism:', err.message);
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			start();
			break;
		case 'resize':
			w = d.width;
			h = d.height;
			dpr = d.dpr || 1;
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = 1;
			break;
	}
};

dark.customCSS:
:root {
	--sw-glass: color-mix(in oklab, var(--color-gray-950) 66%, transparent);
	--sw-sidebar: color-mix(in oklab, var(--color-gray-950) 74%, transparent);
	--sw-bubble: color-mix(in oklab, var(--color-gray-800) 55%, transparent);
	--sw-selected: color-mix(in oklab, var(--tdp-accent) 16%, transparent);
	--sw-line: color-mix(in oklab, var(--tdp-accent) 32%, transparent);
	--sw-ring: color-mix(in oklab, var(--tdp-accent-3) 22%, transparent);
	--sw-pink: var(--tdp-accent);
	--sw-pink-glow: color-mix(in oklab, var(--tdp-accent) 40%, transparent);
	--sw-cyan: var(--tdp-accent-3);
	--sw-cyan-glow: color-mix(in oklab, var(--tdp-accent-3) 45%, transparent);
	--sw-strong: color-mix(in oklab, var(--tdp-accent) 25%, var(--color-gray-50));
	--sw-neon: 0 0 0.6em color-mix(in oklab, var(--tdp-accent) 60%, transparent);
}

/* Neon on a night drive: hot pink headings, cyan links and a cyan focus
   ring; the light modes trade neon for pastel daylight. !important only
   where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--sw-glass) !important;
	border-color: var(--sw-line) !important;
	backdrop-filter: blur(18px) saturate(1.2);
	box-shadow: 0 0 28px -12px var(--sw-pink-glow);
	transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#message-input-container:focus-within {
	border-color: var(--sw-cyan) !important;
	box-shadow: 0 0 0 3px var(--sw-ring), 0 0 32px -10px var(--sw-cyan-glow);
}
.chat-user .rounded-3xl {
	background-color: var(--sw-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--sw-line);
}
#sidebar {
	background-color: var(--sw-sidebar) !important;
	backdrop-filter: blur(20px) saturate(1.2);
	border-inline-end: 1px solid var(--sw-line);
}
#sidebar-chat-item.selected { background-color: var(--sw-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--sw-pink); text-shadow: var(--sw-neon); }
.markdown-prose a { color: var(--sw-cyan); text-decoration-color: var(--sw-cyan-glow); }
.markdown-prose strong { color: var(--sw-strong); }
.markdown-prose blockquote { border-inline-start-color: var(--sw-pink); }
.markdown-prose hr { border-color: var(--sw-line); }
::selection { background-color: var(--sw-pink-glow); }
html { scrollbar-color: var(--sw-line) transparent; }

dark.canvasScript:
/**
 * Title: Retro Sun
 * Description: A synthwave sun with scrolling stripe cutouts sets low in an outer third over a perspective grid that rolls toward you, under calm twinkling stars; the glow swells when the cursor comes near.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const SUN_X         = 0.96;   // where the sun sits, as a share of the width (0-1)
const SUN_SIZE      = 0.12;  // sun radius as a share of the smaller screen side (0.06-0.3)
const HORIZON       = 0.85;   // height of the horizon, as a share of the screen (0.6-0.9)
const STRIPES       = 7;     // stripe cutouts across the sun's lower half (0-14)
const STRIPE_SPEED  = 6;     // how fast the stripes drift down, in px per second (0-30)
const GRID_SPEED    = 0.35;  // how fast the grid rolls toward you (0-2)
const GRID_LINES    = 22;    // vertical grid lines (6-40)
const STAR_COUNT    = 110;   // stars in the sky (0-300)
const GLOW          = 1;     // strength of the sun's glow and the horizon haze (0-2)
const PULSE_SPEED   = 0.5;   // speed of the glow's slow breathing (0-3)
const CURSOR_GLOW   = 1;     // how much the glow swells near the cursor (0-2)
const REDUCED_SPEED = 0.15;  // share of the motion kept under reduced motion (0-1)
const CENTER_CALM   = 0.8;   // how much the grid and stars fade behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band when the page has no chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's accents
const SUN_TOP       = '#ff6ec7';  // sun's upper color when not following the theme
const SUN_BOTTOM    = '#ffb347';  // sun's lower color
const GRID_COLOR    = '#b45cff';  // grid and horizon
/* ──────────────────────────────────────────── */

const MAX_STARS = 300, TAU = Math.PI * 2;

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, column = null;
let top = hex(SUN_TOP), bottom = hex(SUN_BOTTOM), grid = hex(GRID_COLOR), star = [255, 255, 255];
let sunBody, sunCut, sunG, glowSprite, hazeSprite, gridStyle, horizonStyle, starStyle;
let sunR = 100, sunX = 0, horizonY = 0, stripePhase = 0, gridPhase = 0, pulseT = 0;
const sx = new Float32Array(MAX_STARS), sy = new Float32Array(MAX_STARS), ss = new Float32Array(MAX_STARS);
const sp = new Float32Array(MAX_STARS), sph = new Float32Array(MAX_STARS), sa = new Float32Array(MAX_STARS);
let stars = 0;
const mouse = { x: -10000, y: -10000, amount: 0, boost: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
// The chat column's center and the calm band's half-width
function colX() { return column ? column.x : w * 0.5; }
function colHalf() { return column ? column.width * 0.5 + 56 : BAND_WIDTH; }
function band(x) {
	const t = Math.min(1, Math.max(0, (Math.abs(x - colX()) / colHalf() - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		top = hex(t.colors.accent2);
		bottom = mix(hex(t.colors.accent), hex(t.colors.accent2), 0.2);
		grid = hex(t.colors.accent3);
		star = dark ? mix(hex(t.colors.text), [255, 255, 255], 0.5) : hex(t.colors.muted);
	} else star = dark ? [255, 255, 255] : [90, 90, 120];
	if (w) build();
}

// A soft radial sprite in one color
function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.4, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

// A horizontal gradient that fades a stroke over the chat column
function columnFade(col, a) {
	const g = ctx.createLinearGradient(0, 0, w, 0), k = 1 - CENTER_CALM, c = colX() / w, b = colHalf() / w;
	const at = (u) => Math.min(1, Math.max(0, u));
	g.addColorStop(0, rgba(col, a));
	g.addColorStop(at(c - b * 1.25), rgba(col, a));
	g.addColorStop(at(c - b * 0.55), rgba(col, a * k));
	g.addColorStop(at(c + b * 0.55), rgba(col, a * k));
	g.addColorStop(at(c + b * 1.25), rgba(col, a));
	g.addColorStop(1, rgba(col, a));
	return g;
}

// Caches rebuilt on resize, layout and theme change: the sun body, its glow and the grid styles
function build() {
	sunR = Math.max(40, Math.min(w, h) * SUN_SIZE);
	horizonY = Math.round(h * HORIZON);
	// The sun sits just past the calm band on its preferred side, or the other side when that one has no room, inside the chat area
	const L = column ? column.left : 0, R = column ? column.right : w, pref = L + (R - L) * SUN_X;
	// Too big for either margin, it shrinks to fit the wider one rather than sitting on the column
	if (column) {
		const room = Math.max(colX() - colHalf() - L, R - colX() - colHalf());
		sunR = Math.max(24, Math.min(sunR, room / 2.4));
	}
	const lo = L + sunR * 1.1, hi = R - sunR * 1.1, off = colHalf() + sunR * 0.2;
	const right = Math.max(pref, colX() + off), left = Math.min(pref, colX() - off);
	const first = SUN_X > 0.5 ? right : left, other = SUN_X > 0.5 ? left : right;
	sunX = Math.abs(SUN_X - 0.5) <= 0.05 ? pref : first >= lo && first <= hi ? first : other >= lo && other <= hi ? other : first;
	sunX = Math.max(lo, Math.min(hi, sunX));
	const s = Math.ceil(sunR * 2 * dpr) + 4;
	sunBody = new OffscreenCanvas(s, s);
	const g = sunBody.getContext('2d');
	g.setTransform(dpr, 0, 0, dpr, 2, 2);
	const grad = g.createLinearGradient(0, 0, 0, sunR * 2);
	grad.addColorStop(0, rgba(mix(top, [255, 255, 255], dark ? 0.15 : 0), 1));
	grad.addColorStop(0.55, rgba(mix(top, bottom, 0.6), 1));
	grad.addColorStop(1, rgba(bottom, 1));
	g.fillStyle = grad;
	g.beginPath();
	g.arc(sunR, sunR, sunR, 0, TAU);
	g.fill();
	sunCut = new OffscreenCanvas(s, s);
	sunG = sunCut.getContext('2d');
	const a = dark ? 1 : 0.4;
	glowSprite = sprite(256, mix(top, bottom, 0.4), 0.7 * a, 0.22 * a);
	hazeSprite = sprite(256, top, 0.55 * a, 0.22 * a);
	gridStyle = columnFade(grid, dark ? 0.55 : 0.45);
	horizonStyle = columnFade(mix(top, grid, 0.3), dark ? 0.85 : 0.7);
	starStyle = rgba(star, 1);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	build();
	stars = Math.min(MAX_STARS, Math.round(STAR_COUNT * Math.max(0.5, w * h / (1440 * 900))));
	for (let i = 0; i < stars; i++) {
		sx[i] = Math.random() * w;
		sy[i] = Math.pow(Math.random(), 1.2) * horizonY * 0.92;
		ss[i] = Math.random() < 0.15 ? 2 : 1;
		sp[i] = 0.5 + Math.random() * 1.5;
		sph[i] = Math.random() * TAU;
		sa[i] = (0.35 + Math.random() * 0.65) * calm(sx[i]);
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = reduced ? REDUCED_SPEED : 1;
	stripePhase = (stripePhase + STRIPE_SPEED * motion * dt) % 1000;
	gridPhase = (gridPhase + GRID_SPEED * motion * dt) % 1;
	pulseT = (pulseT + PULSE_SPEED * motion * dt) % 1000;
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';

	// Stars, dimmer near the horizon and behind the column
	ctx.fillStyle = starStyle;
	const starA = dark ? 0.8 : 0.35;
	for (let i = 0; i < stars; i++) {
		const tw = 0.45 + 0.55 * Math.abs(Math.sin(now / 1000 * sp[i] * (reduced ? 0.25 : 1) + sph[i]));
		ctx.globalAlpha = starA * sa[i] * tw * (1 - sy[i] / horizonY * 0.7);
		ctx.fillRect(sx[i], sy[i], ss[i], ss[i]);
	}

	// Glow and haze, swelling a little when the cursor lingers near the sun
	mouse.amount = Math.max(0, mouse.amount - dt * 0.5);
	const dx = mouse.x - sunX, dy = mouse.y - horizonY;
	const near = Math.max(0, 1 - Math.sqrt(dx * dx + dy * dy) / (sunR * 3)) * mouse.amount * CURSOR_GLOW;
	mouse.boost += (near - mouse.boost) * Math.min(1, dt * 2);
	const pulse = 0.85 + 0.15 * Math.sin(pulseT * TAU / 4);
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	ctx.globalAlpha = Math.min(1, GLOW * pulse * 0.7 + mouse.boost * 0.35);
	const gr = sunR * 3.6;
	ctx.drawImage(glowSprite, sunX - gr, horizonY - sunR * 0.4 - gr, gr * 2, gr * 2);
	ctx.globalAlpha = Math.min(1, GLOW * 0.55);
	ctx.drawImage(hazeSprite, sunX - w * 0.25, horizonY - h * 0.08, w * 0.5, h * 0.16);
	ctx.globalCompositeOperation = 'source-over';

	// Sun: the cached body, with stripes cut out of its lower half each frame
	const s = sunCut.width;
	sunG.setTransform(1, 0, 0, 1, 0, 0);
	sunG.globalCompositeOperation = 'source-over';
	sunG.clearRect(0, 0, s, s);
	sunG.drawImage(sunBody, 0, 0);
	if (STRIPES > 0) {
		sunG.globalCompositeOperation = 'destination-out';
		sunG.fillStyle = '#000';
		const gap = sunR * 0.8 / STRIPES;
		for (let k = -1; k < STRIPES; k++) {
			const y = sunR * 0.6 + k * gap + (stripePhase % gap);
			const t = (y - sunR * 0.55) / (sunR * 0.8);
			if (t <= 0) continue;
			const thick = gap * (0.1 + 0.5 * t);
			sunG.fillRect(0, (y - thick / 2) * dpr + 2, s, thick * dpr);
		}
	}
	const lift = sunR * 0.35;
	ctx.save();
	ctx.beginPath();
	ctx.rect(sunX - sunR - 2, horizonY - sunR * 2, sunR * 2 + 4, sunR * 2);
	ctx.clip();
	ctx.globalAlpha = dark ? 0.95 : 0.8;
	ctx.drawImage(sunCut, sunX - sunR - 2 / dpr, horizonY - sunR - lift - 2 / dpr, s / dpr, s / dpr);
	ctx.restore();

	// Horizon line
	ctx.globalAlpha = 1;
	ctx.strokeStyle = horizonStyle;
	ctx.lineWidth = 1.5;
	ctx.beginPath();
	ctx.moveTo(0, horizonY);
	ctx.lineTo(w, horizonY);
	ctx.stroke();

	// Grid: lines from a vanishing point under the sun, rows rolling toward the viewer
	const depth = h - horizonY;
	ctx.strokeStyle = gridStyle;
	ctx.lineWidth = 1;
	ctx.globalAlpha = 0.8;
	ctx.beginPath();
	const spread = w * 2.4;
	for (let i = 0; i <= GRID_LINES; i++) {
		const bx = sunX + (i / GRID_LINES - 0.5) * spread;
		ctx.moveTo(sunX + (bx - sunX) * 0.04, horizonY);
		ctx.lineTo(bx, h);
	}
	ctx.stroke();
	for (let r = 0; r < 12; r++) {
		const z = (r + 1 - gridPhase) / 12;
		const y = horizonY + depth * z * z;
		ctx.globalAlpha = Math.min(1, z * 1.6) * 0.85;
		ctx.beginPath();
		ctx.moveTo(0, y);
		ctx.lineTo(w, y);
		ctx.stroke();
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			column = d.column || null;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'layout':
			column = d.column || null;
			if (canvas) size();
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.amount = 1;
			break;
	}
};

